:root {
  /* Follow the OS by default; the <meta name="color-scheme"> override (set from the theme switch) wins when present. */
  color-scheme: light dark;
  &:has(> head > meta[name="color-scheme"][content="dark"]) { color-scheme: dark; }
  &:has(> head > meta[name="color-scheme"][content="light"]) { color-scheme: light; }

  /* Raw palette */
  --bg-light: #f6f7f9;            --bg-dark: #121418;
  --text-light: #1d1f23;          --text-dark: #e6e8eb;
  --surface-light: white;         --surface-dark: #1e2127;
  --header-bg-light: #1d4ed8;     --header-bg-dark: #1e3a8a;
  --border-light: #eee;           --border-dark: #2f343c;
  --muted-bg-light: #e5e7eb;      --muted-bg-dark: #374151;
  --invalid-border-light: #dc2626; --invalid-border-dark: #f87171;
  --invalid-bg-light: #fef2f2;    --invalid-bg-dark: #3b1518;
  --shadow-light: rgb(0 0 0 / 0.1); --shadow-dark: rgb(0 0 0 / 0.5);

  /* Fallback tokens (light) — switched below for browsers without light-dark() */
  --bg: var(--bg-light);
  --text: var(--text-light);
  --surface: var(--surface-light);
  --header-bg: var(--header-bg-light);
  --border: var(--border-light);
  --muted-bg: var(--muted-bg-light);
  --invalid-border: var(--invalid-border-light);
  --invalid-bg: var(--invalid-bg-light);
  --shadow: var(--shadow-light);

  @supports (color: light-dark(red, red)) {
    --bg: light-dark(var(--bg-light), var(--bg-dark));
    --text: light-dark(var(--text-light), var(--text-dark));
    --surface: light-dark(var(--surface-light), var(--surface-dark));
    --header-bg: light-dark(var(--header-bg-light), var(--header-bg-dark));
    --border: light-dark(var(--border-light), var(--border-dark));
    --muted-bg: light-dark(var(--muted-bg-light), var(--muted-bg-dark));
    --invalid-border: light-dark(var(--invalid-border-light), var(--invalid-border-dark));
    --invalid-bg: light-dark(var(--invalid-bg-light), var(--invalid-bg-dark));
    --shadow: light-dark(var(--shadow-light), var(--shadow-dark));
  }
}

/* Fallback for browsers without light-dark(): dark when the OS is dark (unless pinned light), or when pinned dark */
@supports not (color: light-dark(red, red)) {
  @media (prefers-color-scheme: dark) {
    :root:not(:has(> head > meta[name="color-scheme"][content="light"])) {
      --bg: var(--bg-dark); --text: var(--text-dark); --surface: var(--surface-dark);
      --header-bg: var(--header-bg-dark); --border: var(--border-dark); --muted-bg: var(--muted-bg-dark);
      --invalid-border: var(--invalid-border-dark); --invalid-bg: var(--invalid-bg-dark); --shadow: var(--shadow-dark);
    }
  }
  :root:has(> head > meta[name="color-scheme"][content="dark"]) {
    --bg: var(--bg-dark); --text: var(--text-dark); --surface: var(--surface-dark);
    --header-bg: var(--header-bg-dark); --border: var(--border-dark); --muted-bg: var(--muted-bg-dark);
    --invalid-border: var(--invalid-border-dark); --invalid-bg: var(--invalid-bg-dark); --shadow: var(--shadow-dark);
  }
}

body { font-family: system-ui, sans-serif; margin: 0; background: var(--bg); color: var(--text); }
.top { background: var(--header-bg); color: white; padding: 1rem 2rem; display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; justify-content: space-between; }
.top h1 { margin: 0; }
main { max-width: 640px; margin: 2rem auto; display: grid; gap: 1.5rem; }
.card { background: var(--surface); border-radius: 8px; padding: 1.25rem; box-shadow: 0 1px 3px var(--shadow); }
form label { display: block; margin-top: 0.75rem; font-weight: 600; }
form input { width: 100%; padding: 0.5rem; box-sizing: border-box; }
input:invalid { border: 2px solid var(--invalid-border); background: var(--invalid-bg); }
.help-icon { display: inline-grid; place-items: center; width: 1.2em; height: 1.2em; border-radius: 50%; background: var(--muted-bg); font-size: 0.8em; cursor: help; }
#task-list { list-style: none; margin: 0; }
#task-list li { display: flex; justify-content: space-between; padding: 0.5rem 0; border-bottom: 1px solid var(--border); }
button { cursor: pointer; }

/* Theme switch: segmented radio group in the header */
.theme-switch { display: flex; margin: 0; padding: 0; border: 1px solid rgb(255 255 255 / 0.6); border-radius: 999px; overflow: hidden; }
.theme-switch label { display: block; padding: 0.35rem 0.85rem; cursor: pointer; font-size: 0.9rem; }
.theme-switch label + label { border-left: 1px solid rgb(255 255 255 / 0.6); }
.theme-switch input { position: absolute; opacity: 0; pointer-events: none; }
.theme-switch label:has(:checked) { background: white; color: #1e3a8a; font-weight: 600; }
.theme-switch label:has(:focus-visible) { outline: 2px solid white; outline-offset: -4px; }

/* "System" shows what the OS is currently set to */
.system-current-dark { display: none; }
@media (prefers-color-scheme: dark) {
  .system-current-light { display: none; }
  .system-current-dark { display: inline; }
}

.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

